apps=[]
for proc in Path('/proc').glob('[0-9]*/cmdline'):
    try:
        cmd=proc.read_bytes().replace(b'\x00',b' ').decode(errors='replace')
        if '/kit/kit ' in cmd or 'record_worker.py' in cmd: apps.append(int(proc.parent.name))
    except OSError: pass
if apps: raise RuntimeError('Existing application processes; do not start concurrent test: '+str(apps))
if not Path('/tmp/.X11-unix/X20').exists(): raise RuntimeError('Expected desktop display :20 not found')
