child=subprocess.Popen(['/usr/bin/python3','-I','-S','-B',str(OUT/'supervise.py')],stdin=subprocess.DEVNULL,stdout=log,stderr=subprocess.STDOUT,start_new_session=True,cwd=str(OUT))
